INSERT INTO `products` (`id`, `sku`, `barcode`, `name`, `slug`, `category_id`, `description_short`, `description_long`, `has_variant`, `base_price`, `sale_price`, `weight`, `views_count`, `is_active`, `with_stock`, `created_at`, `updated_at`) VALUES
(1, 'KMC', '9315372406586', 'Kemoceng Panjang 280 cm Bisa ditekuk', 'kemoceng-panjang-280-cm-bisa-ditekuk', 1, 'Kemoceng Bisa Panjang Tekuk Microfiber \"Magnet Debu\" Extendable', 'Fitur:\r\n\r\n- 2 in 1 penggunaan, bisa pakai stick atau gagang tangan.\r\n- Penggunaan dengan stick dapat dipanjangkan sampai 82cm, dapat membersihkan langit -langit/ AC/ atas lemari, semua permukaan dengan ketinggian susah dibersihkan.\r\n- Bahan microfiber dapat mengangkat debu dengan sempurna, seperti magnet.\r\n\r\n- Kemoceng dapat dicuci dan dipakai semula kala.\r\n\r\nWarna tersedia : grey\r\nUkuran dengan extention stick : Panjang total dengan stick 280cm\r\n\r\nUkuran hanya kemoceng gagang tangan : 58cm\r\n\r\nPaket yang diterima:\r\n1 kemoceng dengan gagang tangan\r\n1 Stick extendable (dapat di perpanjang)', 0, 38500, 34000, 100, NULL, 1, 1, '2026-07-07 17:33:11', '2026-07-13 15:16:47'),
(2, 'KS-I', '6826023176573', '[𝟐 𝐩𝐜𝐬] Kain Lap Mobil Microfiber Lembut Anti Lecet ukuran 30x30 Serbaguna Praktis', 'kain-lap-mobil-microfiber-lembut-anti-lecet-ukuran-30x30-serbaguna-praktis', 1, '- Bahan Microfiber.\r\n- berpori-pori sangat rapat.\r\n- Sangat mudah menyerap air dan membersihkan kotoran yang menempel tanpa menggores permukaan.', 'Kain Lap Microfiber Mobil Motor 2 Pcs adalah solusi sempurna untuk kebutuhan pembersihan Anda. \r\nDibuat dari bahan microfiber berkualitas tinggi, kain ini menawarkan kelembutan dan efisiensi dalam setiap penggunaan. \r\nDengan desain dua sisi, kain ini memberikan fleksibilitas untuk digunakan pada berbagai permukaan, baik interior maupun eksterior kendaraan. \r\n\r\nKeunggulan Produk: \r\n   - Lembut dan Ramah Lingkungan: Kain ini dirancang untuk memberikan kenyamanan maksimal tanpa merusak permukaan. \r\n   - Menyerap Air: Kemampuan menyerap air yang luar biasa membuat pembersihan menjadi lebih efektif dan cepat. \r\n   - Serbaguna: Cocok untuk membersihkan mobil, motor, dan area lainnya, menjadikannya alat pembersih yang andal. \r\n      Dengan ukuran 30x30 cm, kain lap ini memudahkan Anda dalam menjaga kebersihan kendaraan dengan cara yang praktis dan efisien. \r\n\r\nPilih kain lap ini untuk hasil pembersihan yang optimal setiap saat!', 0, 21500, 18500, 400, NULL, 1, 1, '2026-07-13 13:13:10', '2026-07-13 13:13:10'),
(3, 'TGP', '4162972925724', '1 Lusin (12Pcs) Tutup Gelas Plastik Warna-Warni Untuk Melindungi Minuman dari Debu dan Kotoran', '1-lusin-12pcs-tutup-gelas-plastik-warna-warni-untuk-melindungi-minuman-dari-debu-dan-kotoran', 1, 'Tutup gelas plastik warna-warni menggunakan material plastik aman, kuat, dan mudah dibersihkan untuk pemakaian harian.', 'Ringkas, ringan, dan higienis—tutup gelas plastik warna-warni ini menghadirkan clean and refreshing di meja Anda. Warna cerah yang menyegarkan menghadirkan mood booster untuk rutinitas minum harian, dari kopi pagi yang menenangkan hingga teh sore yang santai.\r\n\r\nKeunggulan Utama\r\n- BPA Free & Durable: Material plastik aman, kuat, dan mudah dibersihkan untuk pemakaian harian.\r\n- Warna-Warni Mudah Dikategorisasi: Bantu bedakan jenis minuman (kopi, teh, air mineral, jus) dengan warna beragam.\r\n- Bantu Jaga Suhu: Membantu menjaga minuman tetap dingin atau panas lebih lama—nyaman dan aman untuk momen santai.\r\n- Ringkas & Praktis: Ukuran pas untuk gelas standar, mudah disimpan dan dibawa ke mana saja.\r\n- Desain Modern: Sentuhan warna cerah yang menyegarkan dan menyatu dengan gaya minimalis bersih.\r\n\r\nCocok Untuk\r\n- Ritual kopi pagi yang menenangkan di meja kerja—fokus dan produktif tanpa repot.\r\n- Brunch santai di rumah—set meja makan harian jadi lebih rapi dan cozy.\r\n- On-the-go: praktis untuk piknik akhir pekan atau perjalanan singkat—tetap nyaman dan aman.\r\n- Jamuan keluarga/pesta kecil—tampilan warna-warni bikin mood booster dan hospitality hangat.\r\n\r\nIsi Paket\r\n- 1 lusin (12 pcs) tutup gelas plastik warna-warni.\r\n\r\n\r\nInstruksi Pemesanan\r\n\r\n- Warna dikirim acak (random mix) sesuai ketersediaan stok.\r\n- Tidak menerima request warna. Silakan pilih paket lusin 12 pcs ini untuk stok warna-warni yang serbaguna.\r\n\r\n\r\n\r\nDetail Produk\r\n\r\n- Diameter: 8 cm\r\n- Material: Plastik\r\n- Kompatibilitas: Gelas/kaleng minuman standar (500 ml)\r\n- Warna: Random mix (acak sesuai stok)', 0, 27500, 22000, 100, NULL, 1, 1, '2026-07-13 13:23:40', '2026-07-13 13:23:40'),
(4, '5PC', '0298969274563', '5pcs Pisau Cukur Kumis Pisau Cukur Rambut Pisau Cukur Jenggot 3 mata silet manual', '5pcs-pisau-cukur-kumis-pisau-cukur-rambut-pisau-cukur-jenggot-3-mata-silet-manual', 1, '5 pcs Pisau Cukur Kumis dan Jenggot ini hadir dengan 3 mata pisau tajam yang memberikan hasil cukuran lebih halus dan nyaman.', 'Pisau Cukur Kumis dan Jenggot ini hadir dengan 3 mata pisau tajam yang memberikan hasil cukuran lebih halus dan nyaman. \r\nPegangan alat cukur dirancang ergonomis untuk kenyamanan maksimal saat digunakan, sehingga Anda bisa mencukur kumis dan jenggot dengan mudah dan presisi. \r\n\r\nKeunggulan Produk: \r\n- Mata pisau tajam untuk hasil cukuran halus \r\n- Pegangan nyaman, mudah digenggam \r\n- Cocok untuk mencukur kumis dan jenggot. \r\n\r\nPisau cukur ini sangat ideal untuk Anda yang menginginkan tampilan rapi setiap saat. \r\nDengan desain yang praktis, alat cukur ini siap menemani rutinitas grooming Anda setiap hari.\r\n\r\nHarga untuk 5pcs', 0, 17500, 15500, 400, NULL, 1, 1, '2026-07-13 14:42:18', '2026-07-13 14:42:18'),
(5, '5SLTP', '9897100288720', 'Selotip Kran Air ukuran 12mm x 0.075mm x 10m', 'selotip-kran-air-ukuran-12mm-x-0075mm-x-10m', 2, '5pcs Seal tape kran air ukuran 1/2\" x 10 meter', 'Tape Isolasi Kran 12mm x 0.075mm x 10m adalah solusi tepat untuk mencegah kebocoran pada kran air dan pipa paralon. \r\nProduk ini memiliki ukuran 12 mm x 0.075 mm x 10 meter, sehingga cocok untuk berbagai kebutuhan perpipaan. \r\nTape ini berfungsi sebagai pelapis pada drat kran sebelum dipasang, memastikan koneksi yang rapat dan tahan lama. \r\nDengan penggunaan yang mudah, tape isolasi ini memudahkan pemasangan dan memastikan sistem perpipaan Anda tetap dalam kondisi prima.\r\n\r\nHarga untuk 5 pcs Seal Tape.', 0, 19000, 17500, 500, NULL, 1, 1, '2026-07-13 14:51:00', '2026-07-13 14:51:00'),
(6, 'KRBS', '4402214324075', 'KRAN/ KERAN TAMAN AIR MERK JORDAN BEST QUALITY', 'kran-keran-taman-air-merk-jordan-best-quality', 2, 'Kran taman merk Jordan', 'Kran Air Tembok ini adalah solusi praktis untuk kebutuhan air di rumah Anda. \r\nDengan desain elegan dan gagang pendek, kran ini mudah dipasang dan cocok untuk berbagai aplikasi seperti taman dan tembok.\r\n\r\nFitur Utama:\r\n- Gagang pendek untuk kemudahan penggunaan\r\n- Tersedia ukuran 1/2 inch dan 3/4 inch untuk instalasi yang pas\r\n- Mudah dipasang di berbagai area\r\n\r\nPilihan Variasi:\r\n- Ukuran: 1/2\r\n- Ukuran: 3/4', 1, NULL, NULL, NULL, NULL, 1, 1, '2026-07-13 15:05:41', '2026-07-13 15:05:41'),
(8, 'KPVC', '9372706354950', 'KRAN AIR TAMAN PVC JORDAN BEST QUALITY', 'kran-air-taman-pvc-jordan-best-quality', 2, 'Keran Air Plastik - Plastik Tahan Lama, Praktis, Mudah Dipasang', 'Kran Air Plastik ini adalah solusi praktis untuk kebutuhan air di rumah Anda. Dibuat dari bahan plastik yang tahan lama, keran ini cocok untuk digunakan di berbagai area seperti kamar mandi, taman, dan kebutuhan sanitasi lainnya.\r\n\r\nKeunggulan Produk:\r\n- Material: Plastik tebal yang memberikan daya tahan ekstra.\r\n- Desain: Model engkol yang mudah digunakan dan dipasang tanpa alat tambahan.\r\n- Ukuran: Kompatibel dengan pipa, memastikan instalasi yang mudah dan cepat.\r\n\r\nFungsi dan Kemudahan:\r\nKran ini dirancang untuk memberikan aliran air yang stabil dan bebas bocor. Dengan desain yang praktis, pemasangan keran ini sangat mudah dan tidak memerlukan alat khusus.\r\n\r\nJadikan Keran Air Plastik ini pilihan utama Anda untuk kebutuhan air di rumah, dengan kualitas yang dijamin bagus dan penggunaan yang mudah.', 1, NULL, NULL, NULL, NULL, 1, 1, '2026-07-13 15:36:30', '2026-07-13 15:36:30'),
(10, 'KDFL1/2', '1125640871314', 'KRAN AIR 1/2\" DOUBLE TYPE 595 FLUSSO', 'kran-air-12-double-type-595-flusso', 2, 'Kran Air Double Flusso - Tahan Lama, Desain Elegan, Penggunaan Serbaguna', 'Kran Air Double Flusso menawarkan solusi praktis dan stylish untuk kebutuhan air di rumah Anda. Dengan desain yang elegan dan tahan lama, kran ini adalah pilihan tepat untuk berbagai area seperti kamar mandi, dapur, dan taman.\r\n\r\nKeunggulan Produk:\r\n- Bahan berkualitas tinggi: Terbuat dari Zinc Alloy yang dilapisi Krom Kilap, memberikan tampilan yang stylish dan elegan.\r\n- Fitur Filter Sistem: Memastikan air yang keluar lebih jernih dan bersih.\r\n- Penggunaan Serbaguna: Cocok untuk kran tembok, kran wudhu, kran taman, dan kran cuci piring.\r\n\r\nDetail Teknis:\r\n- Ukuran Drat: 1/2 inch\r\n- Bahan: Zinc Alloy (Babet) dengan jantung kuningan\r\n- Warna: Krom Kilap\r\n\r\nDengan kran ini, Anda mendapatkan kenyamanan dan kepraktisan dalam satu produk. Cocok untuk mengimbangi debit air yang tinggi dan memastikan kran tetap stabil dan tidak mudah bocor.', 0, 143000, 122500, 250, NULL, 1, 1, '2026-07-13 16:00:17', '2026-07-14 15:43:00'),
(11, 'KFLK', '7165266764900', 'KRAN TEMBOK 100% KUNINGAN KRAN TAMAN FLUSSO', 'kran-tembok-100-kuningan-kran-taman-flusso', 2, 'Dibuat dari bahan kuningan berkualitas, kran ini menawarkan daya tahan yang luar biasa dan performa yang andal.', 'Kran Tembok Kuningan Flusso adalah pilihan tepat untuk kebutuhan air di rumah Anda. Dibuat dari bahan kuningan berkualitas, kran ini menawarkan daya tahan yang luar biasa dan performa yang andal.\r\n\r\nKeunggulan Produk:\r\n- Desain elegan yang mempercantik ruangan Anda.\r\n- Tahan lama dan tidak mudah rusak, cocok untuk penggunaan jangka panjang.\r\n- Sistem filter yang menjaga air tetap jernih dan bersih.\r\n- Menghasilkan aliran air yang deras dan halus.\r\n\r\nSpesifikasi:\r\n- Ukuran: 1/2 dan 3/4\r\n- Berat: 800gr\r\n- Tersedia dalam beberapa model dan motif untuk memenuhi kebutuhan Anda.\r\n\r\nKran ini dapat digunakan untuk air dingin maupun panas, menjadikannya pilihan serbaguna untuk berbagai kebutuhan di rumah. Dengan kualitas yang terjamin, kran ini siap menjadi bagian dari rumah Anda yang lebih baik.', 1, NULL, NULL, NULL, NULL, 1, 1, '2026-07-13 16:16:44', '2026-07-14 15:35:04'),
(13, 'KWF1/2', '0612116833628', 'KRAN AIR WASTAFEL 1/2\" TYPE 852 FLUSSO BEST QUALITY', 'kran-air-wastafel-12-type-852-flusso-best-quality', 2, 'Bahan Terbuat dari Zinc Alloy Dilapisi Powder Coating Black Sehingga Terlihat Lebih Bersih dan Stylist', 'UKURAN :  Drat : 1/2\" \r\n\r\nBerat : 163gr\r\n\r\nTYPE 852 FLUSSO\r\n\r\n\r\n\r\nBAHAN : Zinc Alloy Jantung Kuningan\r\n\r\n\r\nKUALITAS/ KEUNGGULAN :\r\n- Bahan Terbuat dari Zinc Alloy Dilapisi Powder Coating Black Sehingga Terlihat Lebih Bersih dan Stylist\r\n- Produk Lebih Berat dan Berkualitas Agar Kran Stabil dan  Mampu Mengimbangi Debit Air Yang Tinggi, Sehingga Kran Tidak Mudah Bocor\r\n- Sudah di Lengkapi Filter System Sehingga Air Yang Keluar Lebih Jernih dan Bersih\r\n- Keluar Air Deras dan Halus\r\n- Untuk Air Dingin\r\n- Kepala Engkol / Baling\r\n- Tahan Lama, Awet dan Tidak Mudah Rusak', 0, 145000, 112000, 163, NULL, 1, 1, '2026-07-14 12:32:52', '2026-07-14 15:49:17'),
(14, 'SKS1/2', '6806062873089', 'Stop Kran Cabang Single Cabang T Double Stainless - Kran Shower Cabang Satu Dobel - Keran Toilet - Keran Closet Kloset - Stop Kran Cebok', 'stop-kran-cabang-single-cabang-t-double-stainless-kran-shower-cabang-satu-dobel-keran-toilet-keran-closet-kloset-stop-kran-cebok', 2, 'Stop Kran Single atau Double drat 1/2 bahan stainless stell', 'Kran cabang yang bisa di gunakan untuk cabang kran di kamar mandi sesuai kebutuhan. \r\n\r\nBisa untuk Toilet atau shower mandi\r\n\r\n\r\n\r\nMau pakai jet shower dan wastafel secara bersamaan? Gunakan Stop Kran Cabang Double!\r\n\r\nDual outlet, hemat tempat & efisien\r\n\r\nBahan Stainless berkualitas tinggi, tahan tekanan air tinggi\r\n\r\nCocok untuk jet shower, keran cuci tangan, atau mesin cuci\r\n\r\nMudah dipasang sendiri tanpa alat khusus\r\n\r\nSolusi cerdas untuk kamar mandi modern dan multifungsi!\r\n\r\n\r\n\r\nUkuran 1/2\"', 1, NULL, NULL, NULL, NULL, 1, 1, '2026-07-14 12:53:01', '2026-07-14 12:53:01'),
(15, 'KPVCW', '0008282528745', 'Kran Air PVC Kuningan - Keran PVC Air Kuningan', 'kran-air-pvc-kuningan-keran-pvc-air-kuningan', 2, 'Kran PVC Drat Kuningan Warna Warni hadir dengan desain modern dan pilihan warna menarik, membuat kran tidak hanya fungsional tapi juga menambah estetika di rumah Anda.', 'Kran PVC Drat Kuningan Warna Warni hadir dengan desain modern dan pilihan warna menarik, membuat kran tidak hanya fungsional tapi juga menambah estetika di rumah Anda.\r\n\r\n\r\nMerk Random/Acak\r\n\r\nUkuran 1/2\" & 3/4\"\r\n\r\n\r\n\r\nTerbuat dari material PVC berkualitas dengan drat kuningan anti karat, kran ini lebih kuat, tahan lama, serta anti bocor. Cocok digunakan di berbagai kebutuhan rumah tangga maupun outdoor.\r\n\r\n\r\n\r\n Keunggulan Produk:\r\n\r\n✔️ Drat Kuningan Asli – lebih awet & tidak mudah aus\r\n\r\n✔️ Warna Warni Menarik – tampil stylish & berbeda dari kran biasa\r\n\r\n✔️ Anti Bocor & Tahan Tekanan Air\r\n\r\n✔️ Ringan & Mudah Dipasang\r\n\r\n✔️ Awet & Tahan Lama', 1, NULL, NULL, NULL, NULL, 1, 1, '2026-07-14 13:05:03', '2026-07-14 13:05:03'),
(18, 'SKKKEN', '2656519822650', 'Ball Valve / Stop Kran body Kuningan KENTARO Japan', 'ball-valve-stop-kran-body-kuningan-kentaro-japan', 2, 'Ball Valve / stop kran 1/2 heavy duty bahan berkualitas 100% Kuningan.', 'Ball Valve / stop kran heavy duty bahan berkualitas 100% Kuningan. \r\nKuat kokoh dan digunakan pemakaian jangka panjang ( anti bocor )\r\n\r\n\r\nmerk kentaro Japan quality', 1, NULL, NULL, NULL, NULL, 1, 1, '2026-07-15 12:59:25', '2026-07-15 12:59:25'),
(19, 'SKPVCN', '7891636844770', 'Stop kran upvc ball valve NATIONAL anti pecah / bocor', 'stop-kran-upvc-ball-valve-national-anti-pecah-bocor', 2, 'Ball Valve / Stop kran UPVC bahan PVC yang terbaik dan sangat tebal kuat dan tahan pemakaian jangka panjang.', 'Ballvalve/ stop kran bahan terbuat jenis upvc yang berkualitas tinggi. \r\nBahan upvc ini adalah bahan material yang anti pecah dan tahan terhadap cuaca. \r\nTerjamin pemakaian dengan jangka waktu lama. \r\nTidak mudah bocor dipakai. \r\n\r\nPastikan product original merk CPT national.', 1, NULL, NULL, NULL, NULL, 1, 1, '2026-07-15 13:12:39', '2026-07-15 13:12:39'),
